"""Portable inference exports, full-state originals retained, content-hashed delivery."""
import json
from pathlib import Path
import shutil
import torch
from exploration.broad_stream_evaluate import vocabulary_bundle
from training.research_sources import file_sha
from training.t2_real_av import write_json


def main():
    cfg=json.loads(Path("configs/t2/broad_stream.json").read_text()); root=Path(cfg["artifacts"]); choices=json.loads((root/"selection.json").read_text()); bundle=vocabulary_bundle(cfg); manifest={"worlds":{},"actors":{},"external_vocoder":{"name":"charactr/vocos-mel-24khz","revision":"0feb3fdd929bcd6649e0e7c5a688cf7dd012ef21","parameters":13531650},"text_scope":"Separate125M language weights; world text input is fixed CMU pronunciation"}
    for run in cfg["runs"]:
        name=run["id"]; source=root/name/"best.pt"; assert file_sha(source)==choices[name]["checkpoint_sha256"]; ck=torch.load(source,map_location="cpu",weights_only=False); target=bundle/(name+".pt"); payload={k:ck[k] for k in ("model","config","run","step","source_hashes","parameters","dataset_card_sha256")}; payload["selected_full_state_sha256"]=file_sha(source); torch.save(payload,target); manifest["worlds"][name]={"file":target.name,"sha256":file_sha(target),"full_state_sha256":file_sha(source),"parameters":ck["parameters"],"selected_step":ck["step"]}; del ck,payload
    policy=Path("experiments/policy/continuous-sensing-20261105"); actors=json.loads((policy/"selection.json").read_text())
    for world,entry in actors.items():
        ck=torch.load(policy/world/"actor.pt",map_location="cpu",weights_only=False); ck["training_world_checkpoint_sha256"]=ck["world_checkpoint_sha256"]; ck["world_checkpoint_sha256"]=manifest["worlds"][world]["sha256"]; target=bundle/(entry["id"]+".pt"); torch.save(ck,target); manifest["actors"][entry["id"]]={"world":world,"file":target.name,"sha256":file_sha(target),"original_actor_sha256":entry["actor_sha256"],"world_weights_identical":True}
        raw=entry["raw_control"]; ck=torch.load(policy/world/"raw/actor.pt",map_location="cpu",weights_only=False); ck["training_world_checkpoint_sha256"]=ck["world_checkpoint_sha256"]; ck["world_checkpoint_sha256"]=manifest["worlds"][world]["sha256"]; target=bundle/(raw["id"]+".pt"); torch.save(ck,target); manifest["actors"][raw["id"]]={"world":world,"file":target.name,"sha256":file_sha(target),"original_actor_sha256":raw["actor_sha256"],"world_weights_identical":True,"feature_mode":"raw"}
    external=Path("artifacts/decoders/vocos-mel-24khz"); (bundle/"vocos").mkdir(exist_ok=True)
    for name in ("config.yaml","pytorch_model.bin","provenance.json","README.md"):
        if (external/name).exists(): shutil.copyfile(external/name,bundle/"vocos"/name)
    manifest["external_vocoder"].update(weights_sha256=file_sha(bundle/"vocos/pytorch_model.bin"),config_sha256=file_sha(bundle/"vocos/config.yaml")); manifest["codec_files"]={name:file_sha(bundle/name) for name in ("codec.npz","duration_model.json","vocabulary.json","appearance_pixels.npy","appearance_code.npy")}; write_json(bundle/"manifest.json",manifest)
    instructions=["# Portable B1 world fields and sensing actors","","These are inference exports of the validation-selected weights. Every neural tensor is checked against the full retained training state. Full optimizers/RNG, final states, curves and sources remain one directory above. manifest.json binds each actor to its exact exported world and records all codec/renderer hashes.","","| World | Variant / seed | Trained neural weights | Selected update |","|---|---|---:|---:|"]
    for run in cfg["runs"]:
        entry=manifest["worlds"][run["id"]]; instructions.append(f"| {run['id']} | {run['variant']} / {run['seed']} | {entry['parameters']:,} | {entry['selected_step']} |")
    instructions += ["","Worlds801/802/803/804 pair SLWM/Transformer at seeds91/92. Actors101–104 use their shared fields;111–114 use matched simple sensor statistics. The other worlds are registered controls, not test-selected winners. The world text edge is CMU pronunciation with train-estimated timing, not the separate125M general language model.","","Run from the repository root with research-stream dependencies, matching PyTorch/Torchaudio and FFmpeg/FFprobe. Replace INPUT.wav/INPUT.mp4 with ordinary files. Defaults use CPU; add --device cuda for the recorded GPU path. Every output retains proposals, actual field text, state traces and media.","","```bash",f"python -m exploration.broad_stream_infer --checkpoint {bundle}/EXP-T2-801.pt --codec-dir {bundle} --mode audio-to-video --audio INPUT.wav --seconds 40.96 --output /tmp/slwm_audio_to_video",f"python -m exploration.broad_stream_infer --checkpoint {bundle}/EXP-T2-801.pt --codec-dir {bundle} --mode video-to-audio --video INPUT.mp4 --seconds 40.96 --output /tmp/slwm_video_to_audio",f"python -m exploration.broad_stream_infer --checkpoint {bundle}/EXP-T2-801.pt --codec-dir {bundle} --mode text-to-av --text 'This passage supplies the words and estimated timing for the phonetic edge.' --min-text-seconds 40.96 --output /tmp/slwm_text_to_av",f"python -m exploration.stream_sensing_infer --world {bundle}/EXP-T2-801.pt --actor {bundle}/EXP-P1-101.pt --codec-dir {bundle} --audio INPUT.wav --video INPUT.mp4 --goal both --pace --output /tmp/slwm_continuous_sensing","```","","Audio-to-video keeps the supplied soundtrack and predicts64x64 face motion over a supplied training appearance. Video-to-audio generates sound with separately frozen13,531,650-weight Vocos; its CLI never decodes source sound. Text generation uses the provided words, with no reference timing. Stretching a short prompt to40.96s is an interface example, not evidence of naturally fluent long speech; the registered long passages and all failures are in ../watch.html.","","The actor consumes at least42.325s of files for one bootstrap plus30 decisions. Paced replay waits for recorded chunk availability before processing it, makes decisions continuously without another user request and checks weight invariance. Features are prepared ahead of replay. These sensing actions do not control physical motion. Read ../report.md and the P1 report before interpreting outputs.","","The model waits for1.365s chunks plus FFT support. Offline Vocos rendering additionally uses512ms future predicted mel context. This bundle does not establish live microphone transport, fast motor control, general scene video, factual language understanding or a converged joint125M multimodal model."]
    (bundle/"README.md").write_text("\n".join(instructions)+"\n")
    textcfg=json.loads(Path("configs/t1/fineweb_extend_v2.json").read_text()); textroot=Path(textcfg["artifacts"]); text_choices=json.loads((textroot/"selection.json").read_text()); exports=textroot/"inference_exports"; exports.mkdir(exist_ok=True); text_manifest={}
    for run in textcfg["runs"]:
        name=run["id"]; source=textroot/name/"best.pt"; assert file_sha(source)==text_choices[name]["checkpoint_sha256"]; ck=torch.load(source,map_location="cpu",weights_only=False); payload={k:ck[k] for k in ("model","config","run","step","total_token_equivalent_step","provenance")}; target=exports/(name+".pt"); torch.save(payload,target); text_manifest[name]={"file":target.name,"sha256":file_sha(target),"full_state_sha256":file_sha(source),"training_tokens":ck["total_token_equivalent_step"]*16384}; del ck,payload
    write_json(exports/"manifest.json",text_manifest)
    (exports/"README.md").write_text("# Separate GPT-2-scale language exports\n\nValidation-selected124/125M language weights after the registered151M-token continuation. These weights are separate from the24M audiovisual fields. Full optimizer/RNG, final states, sources, all fixed samples and the fresh-test/compute report remain one directory above. Check manifest.json for SHA256 and actual selected token exposure.\n\nFrom the repository root, run `python -m exploration.scale_text_infer --checkpoint "+str(exports/"EXP-T1-222.pt")+" --prompt 'The experiment shows' --device cpu`. This is raw512-context continuation, not an instruction-following factual assistant. Both architectures/seeds, including poor outputs, are retained.\n")
    write_json(root/"export_complete.json",{"world_manifest_sha256":file_sha(bundle/"manifest.json"),"text_manifest_sha256":file_sha(exports/"manifest.json"),"world_exports":len(manifest["worlds"]),"actor_exports":len(manifest["actors"]),"text_exports":len(text_manifest)}); print(json.dumps({"world_exports":len(manifest["worlds"]),"actor_exports":len(manifest["actors"]),"text_exports":len(text_manifest)}),flush=True)


if __name__=="__main__": main()
